import Foundation

/**
 ХАРАКТЕРИСТИКИ ЭЛЕКТРОНИКИ В ФИЛЬТРАХ (владелец 30.09.2026: «в каждом разделе свои фильтры поиска»).

 Источник — inc/e_specs.php сайта (MK_ESPECS на странице ленты, E_SPECS в js/cab-refs.js): у каждой категории
 электроники свой набор — слот объявления (cpu, gpu, ram, storage, year), подпись, единица, «число» и значения. Лист
 «Фильтры» строит его так же, как mkFacetSet и _mkESpecFacets сайта:
   · раздел ищем вверх по предкам; компьютеры и телефоны (mkTechKind: pc, phone) не подменяем — у них свои группы;
   · значения списком — чипами; уходят как MKF_SRV_LIST: cpu→gear, gpu→fuel, ram→ramv, storage→stov, через «|»;
   · число на ram и storage — «от — до» по значениям справочника: kmin/kmax и emin/emax (MKF_SRV_RANGE); терабайты
     переводим в гигабайты, как mkFacetNum сайта и $__стор в inc/db.php;
   · число на cpu и gpu (частота монитора, мощность блока, видеопамять) сайт режет только на странице — сервер такие
     диапазоны не отбирает; у нас это чипы значений (gear/fuel списком), чтобы отбирал сервер;
   · год выпуска — группа «Год выпуска» (ymin/ymax).
 Подписи — на языке телефона (es_<k>, es_u_<uk>), значения показываем через ev_<ключ>, а в запрос уходят русские
 строки: сервер сравнивает их точно.

 Встроенный справочник — копия inc/e_specs.php на 30.09.2026. Если за запуск приложение уже скачало js/cab-refs.js
 (мастер подачи, PostingRefs), берём наборы оттуда — они свежее.
 */

/// Характеристика электроники — строка E_SPECS.
struct ХарактеристикаЭлектроники: Hashable, Sendable {
    /// Слот объявления: cpu, gpu, ram, storage, year.
    let колонка: String
    /// Ключ подписи (es_<ключ>) и русская подпись.
    let ключ: String
    let подписьРу: String
    /// Единица (русская) и её ключ (es_u_<ключ>).
    let единица: String
    let ключЕдиницы: String
    /// num — число: у ram и storage это «от — до».
    let число: Bool
    let значения: [String]

    /// Подпись на языке телефона: «Диагональ, дюйм».
    var подпись: String {
        let имя = ХарактеристикиЭлектроники.перевод("es_" + ключ) ?? подписьРу
        guard !единица.isEmpty else { return имя }
        let ед = ХарактеристикиЭлектроники.перевод("es_u_" + ключЕдиницы) ?? единица
        return имя + ", " + ед
    }

    /// Диапазон «от — до» (kmin/kmax, emin/emax), а не чипы.
    var диапазоном: Bool { число && (колонка == "ram" || колонка == "storage") }

    /// Чипы значений (gear, fuel, ramv, stov).
    var чипами: Bool { !диапазоном && колонка != "year" && !значения.isEmpty }
}

/// Наборы из скачанного js/cab-refs.js — пишет разбор справочников подачи (в фоне), читает лист фильтров.
final class ХранилищеХарактеристик: @unchecked Sendable {
    static let общее = ХранилищеХарактеристик()
    private let замок = NSLock()
    private var наборы: [String: [ХарактеристикаЭлектроники]] = [:]

    func записать(_ новые: [String: [ХарактеристикаЭлектроники]]) {
        guard !новые.isEmpty else { return }
        замок.lock()
        наборы = новые
        замок.unlock()
    }

    func набор(_ раздел: String) -> [ХарактеристикаЭлектроники]? {
        замок.lock()
        defer { замок.unlock() }
        return наборы[раздел]
    }
}

enum ХарактеристикиЭлектроники {
    /// Набор раздела — вверх по предкам, как mkFacetSet; у компьютеров и телефонов — пусто.
    static func набор(_ раздел: String) -> [ХарактеристикаЭлектроники] {
        var текущий: String? = раздел
        var шаги = 0
        while let т = текущий, !т.isEmpty, шаги < 12 {
            шаги += 1
            if !ФильтрыЛенты.видТехники(т).isEmpty { return [] }
            if let свежий = ХранилищеХарактеристик.общее.набор(т), !свежий.isEmpty { return свежий }
            if let свой = встроенные[т], !свой.isEmpty { return свой }
            текущий = РазделыСайта.родитель(т)
        }
        return []
    }

    /// Значение на языке телефона (ev_<ключ>); незнакомое — как есть.
    static func показ(_ значение: String) -> String {
        guard let ключ = ключиЗначений[значение] else { return значение }
        return перевод("ev_" + ключ) ?? значение
    }

    /// Число для kmin/emin: «512GB» — 512, «1TB» — 1024 (mkFacetNum сайта), «27» — 27.
    static func вЧисло(_ значение: String) -> String? {
        let строчное = значение.lowercased()
        let цифры = String(строчное.filter { ($0.isASCII && $0.isNumber) || $0 == "." })
        guard var n = Double(цифры), n > 0 else { return nil }
        if строчное.contains("tb") || строчное.contains("тб") { n *= 1024 }
        return ДиапазонФильтра.вЗапрос(n)
    }

    static func перевод(_ ключ: String) -> String? {
        let язык = String((Locale.preferredLanguages.first ?? "ru").prefix(2))
        return переводы[язык]?[ключ] ?? переводы["ru"]?[ключ]
    }

    /// Строка E_SPECS из cab-refs.js (разбор справочников подачи) — для хранилища.
    static func строка(поле: String, подпись: String, единица: String, число: Bool, значения: [String],
                       ключ: String, ключЕдиницы: String) -> ХарактеристикаЭлектроники {
        ХарактеристикаЭлектроники(колонка: поле, ключ: ключ, подписьРу: подпись, единица: единица,
                                  ключЕдиницы: ключЕдиницы, число: число, значения: значения)
    }

    // MARK: Встроенный справочник

    private struct СыраяСтрока: Decodable {
        let f: String
        let n: String
        let u: String?
        let num: Int?
        let v: [String]?
        let k: String?
        let uk: String?
    }

    private static let встроенные: [String: [ХарактеристикаЭлектроники]] = {
        guard let данные = снимокНаборов.data(using: .utf8),
              let сырые = try? JSONDecoder().decode([String: [СыраяСтрока]].self, from: данные) else { return [:] }
        var итог: [String: [ХарактеристикаЭлектроники]] = [:]
        for (раздел, строки) in сырые {
            итог[раздел] = строки.map { с in
                ХарактеристикаЭлектроники(колонка: с.f, ключ: с.k ?? "", подписьРу: с.n, единица: с.u ?? "",
                                          ключЕдиницы: с.uk ?? "", число: (с.num ?? 0) != 0, значения: с.v ?? [])
            }
        }
        return итог
    }()

    private static let переводы: [String: [String: String]] = {
        guard let данные = снимокПереводов.data(using: .utf8),
              let итог = try? JSONDecoder().decode([String: [String: String]].self, from: данные) else { return [:] }
        return итог
    }()

    private static let ключиЗначений: [String: String] = {
        guard let данные = снимокЗначений.data(using: .utf8),
              let итог = try? JSONDecoder().decode([String: String].self, from: данные) else { return [:] }
        return итог
    }()

